/**
 * The numbered list of sources a reply cites (`design/components/source-list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/source-list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { Icon, MEMBER_PROVIDERS, useMember, type Each } from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/source-list.module.css'

export interface CitationSource {
  title: string
  href: string
  domain?: string
  snippet?: string
}

/** The numbered list of sources a reply cites: the inputs it takes, by the React member's prop names. */
export interface SourceListProps {
  /**
   * The list's accessible name, such as "Sources" in the app's language.
   */
  label: string
  /**
   * The sources in the order the reply numbers them, rendered as given and never sorted.
   */
  sources: CitationSource[]
}

/** The numbered list of sources a reply cites. */
@Component({
  selector: 'pm-source-list',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Icon],
  // prettier-ignore
  template: `@if (e1()) {<section
[attr.class]="e2()"
[attr.aria-label]="e3()"
data-member="source-list"
><!-- heading -->
<span
[attr.class]="e4()"
aria-hidden="true"
><pm-icon
name="cite"
size="sm"
></pm-icon>{{ e3() }}</span>
<!-- list -->
<ol
[attr.class]="e5()"
>@for (source of e6(); track e7($index); let position = $index) {<!-- item -->
<li
[attr.class]="e8()"
><!-- index -->
<span
[attr.class]="e9()"
aria-hidden="true"
>{{ e10(position) }}</span>
<!-- body -->
<span
[attr.class]="e11()"
><!-- title -->
<a
[attr.class]="e12()"
[attr.href]="e13(source)"
target="_blank"
rel="noreferrer"
>{{ e14(source) }}<span
[attr.class]="e15()"
><pm-icon
name="open-external"
size="sm"
></pm-icon></span></a>
@if (e16(source)) {<!-- domain -->
<span
[attr.class]="e17(source)"
>{{ e18(source) }}</span>}
@if (e19(source)) {<!-- snippet -->
<span
[attr.class]="e20(source)"
>{{ e21(source) }}</span>}</span></li>}</ol></section>}`,
})
export class SourceList {
  /**
   * The list's accessible name, such as "Sources" in the app's language.
   */
  readonly label = input.required<SourceListProps['label']>()
  /**
   * The sources in the order the reply numbers them, rendered as given and never sorted.
   */
  readonly sources = input.required<SourceListProps['sources']>()
  protected readonly $ = useMember({
    events: [],
    props: { label: () => this.label(), sources: () => this.sources() },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return this.$p.sources.length > 0
  }

  protected e2() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return styles.root
  }

  protected e3() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return this.$p.label
  }

  protected e4() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return styles.heading
  }

  protected e5() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return styles.list
  }

  e6() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return this.$p.sources
  }

  protected e7(position: number) {
    return position
  }

  protected e8() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return styles.item
  }

  protected e9() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return styles.index
  }

  protected e10(position: number) {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return position + 1
  }

  protected e11() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return styles.body
  }

  protected e12() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return styles.title
  }

  protected e13(source: Each<ReturnType<SourceList['e6']>>) {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return source.href
  }

  protected e14(source: Each<ReturnType<SourceList['e6']>>) {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return source.title
  }

  protected e15() {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return styles.glyph
  }

  protected e16(source: Each<ReturnType<SourceList['e6']>>) {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return source.domain !== undefined
  }

  protected e17(source: Each<ReturnType<SourceList['e6']>>) {
    if (!(this.$p.sources.length > 0)) return undefined as never
    if (!(source.domain !== undefined)) return undefined as never
    return styles.domain
  }

  protected e18(source: Each<ReturnType<SourceList['e6']>>) {
    if (!(this.$p.sources.length > 0)) return undefined as never
    if (!(source.domain !== undefined)) return undefined as never
    return source.domain
  }

  protected e19(source: Each<ReturnType<SourceList['e6']>>) {
    if (!(this.$p.sources.length > 0)) return undefined as never
    return source.snippet !== undefined
  }

  protected e20(source: Each<ReturnType<SourceList['e6']>>) {
    if (!(this.$p.sources.length > 0)) return undefined as never
    if (!(source.snippet !== undefined)) return undefined as never
    return styles.snippet
  }

  protected e21(source: Each<ReturnType<SourceList['e6']>>) {
    if (!(this.$p.sources.length > 0)) return undefined as never
    if (!(source.snippet !== undefined)) return undefined as never
    return source.snippet
  }
}
